CREATE SCHEMA IF NOT EXISTS metadata;
CREATE SCHEMA IF NOT EXISTS ods;
CREATE SCHEMA IF NOT EXISTS dim;
CREATE SCHEMA IF NOT EXISTS dwd;
CREATE SCHEMA IF NOT EXISTS dws;
CREATE SCHEMA IF NOT EXISTS ads;
CREATE TABLE IF NOT EXISTS metadata.data_batch(id uuid PRIMARY KEY, organization_id text NOT NULL, source_name text NOT NULL, sha256 text NOT NULL, status text NOT NULL, data_kind text NOT NULL CHECK(data_kind IN ('simulated','uploaded')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,sha256), UNIQUE(organization_id,id));
CREATE TABLE IF NOT EXISTS ods.raw_vouchers(organization_id text NOT NULL,batch_id uuid NOT NULL,row_number integer NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(batch_id,row_number), FOREIGN KEY(organization_id,batch_id) REFERENCES metadata.data_batch(organization_id,id));
CREATE TABLE IF NOT EXISTS metadata.rejected_rows(organization_id text NOT NULL,batch_id uuid NOT NULL,row_number integer NOT NULL,rule_code text NOT NULL,message text NOT NULL,payload jsonb NOT NULL, FOREIGN KEY(organization_id,batch_id) REFERENCES metadata.data_batch(organization_id,id));
CREATE TABLE IF NOT EXISTS dim.account(organization_id text NOT NULL,code text NOT NULL,name text NOT NULL,category text NOT NULL CHECK(category IN ('revenue','cost','expense','asset','liability','equity','other')),mapping_version text NOT NULL,PRIMARY KEY(organization_id,code));
CREATE TABLE IF NOT EXISTS dwd.fact_journal_entry(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,organization_id text NOT NULL,batch_id uuid NOT NULL,row_number integer NOT NULL,source_system text NOT NULL,voucher_no text NOT NULL,line_no integer NOT NULL,posting_date date NOT NULL,account_code text NOT NULL,department_code text,currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),debit numeric(20,2) NOT NULL CHECK(debit>=0),credit numeric(20,2) NOT NULL CHECK(credit>=0),CHECK(debit=0 OR credit=0), UNIQUE(organization_id,source_system,voucher_no,line_no,posting_date),FOREIGN KEY(organization_id,account_code) REFERENCES dim.account(organization_id,code),FOREIGN KEY(organization_id,batch_id) REFERENCES metadata.data_batch(organization_id,id),FOREIGN KEY(batch_id,row_number) REFERENCES ods.raw_vouchers(batch_id,row_number));
CREATE UNIQUE INDEX IF NOT EXISTS journal_business_year ON dwd.fact_journal_entry(organization_id,source_system,voucher_no,line_no,extract(year FROM posting_date));
CREATE TABLE IF NOT EXISTS metadata.data_lineage(organization_id text NOT NULL,source text NOT NULL,target text NOT NULL,batch_id uuid NOT NULL,transform_version text NOT NULL,PRIMARY KEY(batch_id,source,target),FOREIGN KEY(organization_id,batch_id) REFERENCES metadata.data_batch(organization_id,id));
CREATE TABLE IF NOT EXISTS metadata.audit_log(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,organization_id text NOT NULL,actor_id text NOT NULL,action text NOT NULL,resource text NOT NULL,trace_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE VIEW dws.monthly_finance AS SELECT f.organization_id,to_char(posting_date,'YYYY-MM') AS period,currency,sum(CASE WHEN category='revenue' THEN credit-debit ELSE 0 END)::numeric(20,2) revenue,sum(CASE WHEN category='cost' THEN debit-credit ELSE 0 END)::numeric(20,2) cost,sum(CASE WHEN category='expense' THEN debit-credit ELSE 0 END)::numeric(20,2) expense,array_agg(DISTINCT f.batch_id) batch_ids,'finance-v1'::text metric_version,array_agg(DISTINCT b.data_kind) data_kinds FROM dwd.fact_journal_entry f JOIN dim.account a ON (a.organization_id,a.code)=(f.organization_id,f.account_code) JOIN metadata.data_batch b ON b.id=f.batch_id GROUP BY f.organization_id,to_char(posting_date,'YYYY-MM'),currency;
CREATE OR REPLACE VIEW ads.finance_dashboard AS SELECT *,revenue-cost gross_profit,revenue-cost-expense operating_profit,(revenue-cost)/nullif(revenue,0) gross_margin FROM dws.monthly_finance;
